classdef NormalStartUp < cassette.simulation.turbinestate.BaseState    %OPERATION Summary of this class goes here    %   Detailed explanation goes here    properties        initialpitch    end    methods        function obj = NormalStartUp(yaw,initialpitch)            obj@cassette.simulation.turbinestate.BaseState(yaw)                        cassette.Utils.mustBeDegrees(initialpitch,"Initial pitch angle")            obj.initialpitch=initialpitch;        end    end    methods        function to_bladed(obj,template)            arguments                obj                template cassette.templates.BladedTemplate            end            % set turbine state to operational in both places in IN file            template.replaceProperty("CALCN",13)            index_runconfig=template.findLine("<RunConfiguration>",method="contains");            template.replaceXMLProperty("Calculation",13,after_index=index_runconfig)            % set yaw error            template.replaceProperty("INIMD",obj.yaw*pi/180)                        % set initial pitch            template.replaceProperty("STARTPIT",obj.initialpitch*pi/180)        end    endend